"""Filter expression module for vector store metadata filtering.

Provides a small, composable, serializable filter algebra:

    from graphrag_vectors.filtering import F

    expr = (F.category == "animal") & (F.year >= 2020)
    expr.evaluate({"category": "animal", "year": 2021})  # True

Filter expressions support ``&`` (AND), ``|`` (OR) and ``~`` (NOT) operators and
round-trip through Pydantic ``model_dump()`` / ``model_validate()``.
"""

from __future__ import annotations

from enum import Enum
from typing import Annotated, Any, Literal, Union

from pydantic import BaseModel, Field


class Operator(str, Enum):
    """Comparison operators supported by a :class:`Condition`."""

    eq = "eq"
    ne = "ne"
    gt = "gt"
    gte = "gte"
    lt = "lt"
    lte = "lte"
    in_ = "in_"


class FilterExpr(BaseModel):
    """Abstract base class for all filter expressions."""

    def evaluate(self, record: dict) -> bool:
        """Evaluate this expression against a record dict."""
        raise NotImplementedError

    def __and__(self, other: FilterExpr) -> AndExpr:
        """Combine with another expression using logical AND (flattened)."""
        left = self.and_ if isinstance(self, AndExpr) else [self]
        right = other.and_ if isinstance(other, AndExpr) else [other]
        return AndExpr(and_=[*left, *right])

    def __or__(self, other: FilterExpr) -> OrExpr:
        """Combine with another expression using logical OR (flattened)."""
        left = self.or_ if isinstance(self, OrExpr) else [self]
        right = other.or_ if isinstance(other, OrExpr) else [other]
        return OrExpr(or_=[*left, *right])

    def __invert__(self) -> FilterExpr:
        """Negate this expression; double-negation cancels out."""
        if isinstance(self, NotExpr):
            return self.not_
        return NotExpr(not_=self)


class Condition(FilterExpr):
    """A single field comparison condition."""

    kind: Literal["condition"] = "condition"
    field: str
    operator: Operator
    value: Any = None

    def __init__(
        self,
        field: str | None = None,
        operator: Operator | None = None,
        value: Any = None,
        **data: Any,
    ):
        if field is not None:
            data.setdefault("field", field)
        if operator is not None:
            data.setdefault("operator", operator)
        if value is not None:
            data.setdefault("value", value)
        super().__init__(**data)

    def evaluate(self, record: dict) -> bool:
        """Return the result of applying the operator, or False if field absent."""
        if self.field not in record:
            return False
        actual = record[self.field]
        op = self.operator
        if op == Operator.eq:
            return actual == self.value
        if op == Operator.ne:
            return actual != self.value
        if op == Operator.in_:
            try:
                return actual in self.value
            except TypeError:
                return False
        try:
            if op == Operator.gt:
                return actual > self.value
            if op == Operator.gte:
                return actual >= self.value
            if op == Operator.lt:
                return actual < self.value
            if op == Operator.lte:
                return actual <= self.value
        except TypeError:
            return False
        return False


class AndExpr(FilterExpr):
    """Logical AND of a list of filter expressions."""

    kind: Literal["and"] = "and"
    and_: list[FilterExprUnion]

    def __init__(self, and_: list[FilterExpr] | None = None, **data: Any):
        if and_ is not None:
            data.setdefault("and_", and_)
        super().__init__(**data)

    def evaluate(self, record: dict) -> bool:
        """Return True only if every sub-expression evaluates to True."""
        return all(expr.evaluate(record) for expr in self.and_)


class OrExpr(FilterExpr):
    """Logical OR of a list of filter expressions."""

    kind: Literal["or"] = "or"
    or_: list[FilterExprUnion]

    def __init__(self, or_: list[FilterExpr] | None = None, **data: Any):
        if or_ is not None:
            data.setdefault("or_", or_)
        super().__init__(**data)

    def evaluate(self, record: dict) -> bool:
        """Return True if at least one sub-expression evaluates to True."""
        return any(expr.evaluate(record) for expr in self.or_)


class NotExpr(FilterExpr):
    """Logical NOT of a single filter expression."""

    kind: Literal["not"] = "not"
    not_: FilterExprUnion

    def __init__(self, not_: FilterExpr | None = None, **data: Any):
        if not_ is not None:
            data.setdefault("not_", not_)
        super().__init__(**data)

    def evaluate(self, record: dict) -> bool:
        """Return the negation of the inner expression."""
        return not self.not_.evaluate(record)


# Discriminated union used for (de)serialization of nested expressions.
FilterExprUnion = Annotated[
    Union[Condition, AndExpr, OrExpr, NotExpr],
    Field(discriminator="kind"),
]

AndExpr.model_rebuild()
OrExpr.model_rebuild()
NotExpr.model_rebuild()
Condition.model_rebuild()


class _FieldProxy:
    """Proxy returned by attribute access on :data:`F` to build conditions."""

    __hash__ = None  # type: ignore[assignment]

    def __init__(self, name: str):
        self.name = name

    def __eq__(self, other: Any) -> Condition:  # type: ignore[override]
        return Condition(self.name, Operator.eq, other)

    def __ne__(self, other: Any) -> Condition:  # type: ignore[override]
        return Condition(self.name, Operator.ne, other)

    def __gt__(self, other: Any) -> Condition:
        return Condition(self.name, Operator.gt, other)

    def __ge__(self, other: Any) -> Condition:
        return Condition(self.name, Operator.gte, other)

    def __lt__(self, other: Any) -> Condition:
        return Condition(self.name, Operator.lt, other)

    def __le__(self, other: Any) -> Condition:
        return Condition(self.name, Operator.lte, other)

    def in_(self, values: list) -> Condition:
        """Build a membership condition against a list of values."""
        return Condition(self.name, Operator.in_, list(values))


class _FieldBuilder:
    """Fluent builder: ``F.fieldname`` yields a :class:`_FieldProxy`."""

    def __getattr__(self, name: str) -> _FieldProxy:
        return _FieldProxy(name)


F = _FieldBuilder()

__all__ = [
    "AndExpr",
    "Condition",
    "F",
    "FilterExpr",
    "NotExpr",
    "Operator",
    "OrExpr",
]
