"""The LanceDB vector storage implementation package."""

from datetime import datetime, timezone
from typing import Any

import lancedb
import numpy as np
import pyarrow as pa

from graphrag_vectors.filtering import FilterExpr
from graphrag_vectors.timestamp import _timestamp_fields_for, explode_timestamp
from graphrag_vectors.types import TextEmbedder
from graphrag_vectors.vector_store import (
    VectorStore,
    VectorStoreDocument,
    VectorStoreSearchResult,
)

# The built-in lifecycle timestamp fields, always present and always exploded.
_BUILTIN_DATE_FIELDS = ("create_date", "update_date")

# Mapping of the declared type strings to pyarrow types.
_ARROW_TYPES: dict[str, pa.DataType] = {
    "str": pa.string(),
    "int": pa.int64(),
    "float": pa.float64(),
    "bool": pa.bool_(),
}


def _now_iso() -> str:
    """Return the current UTC time as an ISO 8601 string."""
    return datetime.now(timezone.utc).isoformat()


class LanceDBVectorStore(VectorStore):
    """LanceDB vector storage implementation."""

    def __init__(
        self,
        db_uri: str = "lancedb",
        fields: dict[str, str] | None = None,
        **kwargs: Any,
    ):
        super().__init__(**kwargs)
        self.db_uri = db_uri
        self.fields = dict(fields or {})

    def connect(self) -> Any:
        """Connect to the vector storage."""
        self.db_connection = lancedb.connect(self.db_uri)

        if self.index_name and self.index_name in self.db_connection.table_names():
            self.document_collection = self.db_connection.open_table(self.index_name)

    # ------------------------------------------------------------------
    # Schema helpers
    # ------------------------------------------------------------------
    def _metadata_column_types(self) -> dict[str, str]:
        """Return the full metadata column -> type-string map (dates exploded)."""
        cols: dict[str, str] = {}
        for name, typ in self.fields.items():
            if typ == "date":
                cols[name] = "str"
                cols.update(_timestamp_fields_for(name))
            else:
                cols[name] = typ
        for name in _BUILTIN_DATE_FIELDS:
            if name not in cols:
                cols[name] = "str"
                cols.update(_timestamp_fields_for(name))
        return cols

    def _date_fields(self) -> list[str]:
        """Return the names of all fields that should be exploded as timestamps."""
        dates = [name for name, typ in self.fields.items() if typ == "date"]
        for name in _BUILTIN_DATE_FIELDS:
            if name not in dates:
                dates.append(name)
        return dates

    def _build_schema(self) -> pa.Schema:
        """Build the pyarrow schema for the backing table."""
        fields = [
            pa.field(self.id_field, pa.string()),
            pa.field(self.vector_field, pa.list_(pa.float32(), self.vector_size)),
        ]
        for name, typ in self._metadata_column_types().items():
            fields.append(pa.field(name, _ARROW_TYPES[typ]))
        return pa.schema(fields)

    def create_index(self) -> None:
        """Create an empty table (zero documents) with the configured schema."""
        self.document_collection = self.db_connection.create_table(
            self.index_name if self.index_name else "",
            schema=self._build_schema(),
            mode="overwrite",
        )

    # ------------------------------------------------------------------
    # Row building
    # ------------------------------------------------------------------
    def _build_row(self, document: VectorStoreDocument, base: dict | None = None) -> dict:
        """Build a fully-populated row dict for the given document."""
        src: dict[str, Any] = dict(base or {})
        src.update(document.data or {})

        # Explode all date fields present in the source data.
        for name in self._date_fields():
            if src.get(name):
                src.update(explode_timestamp(src[name], name))

        vector = (
            [float(v) for v in document.vector]
            if document.vector is not None
            else [0.0] * self.vector_size
        )

        row: dict[str, Any] = {
            self.id_field: str(document.id),
            self.vector_field: vector,
        }
        for name in self._metadata_column_types():
            row[name] = src.get(name)
        return row

    def load_documents(self, documents: list[VectorStoreDocument]) -> None:
        """Load documents into vector storage."""
        rows = []
        for document in documents:
            if document.vector is None or len(document.vector) != self.vector_size:
                continue
            data = dict(document.data or {})
            if not data.get("create_date"):
                data["create_date"] = _now_iso()
            document = VectorStoreDocument(
                id=document.id, vector=document.vector, data=data
            )
            rows.append(self._build_row(document))

        if rows:
            self.document_collection.add(rows)

    def insert(self, document: VectorStoreDocument) -> None:
        """Insert a single document, auto-populating create_date if missing."""
        data = dict(document.data or {})
        if not data.get("create_date"):
            data["create_date"] = _now_iso()
        document = VectorStoreDocument(
